    ('ac28b46b-542e-48b7-adf9-32da0efd74c1'::uuid, 'site_type', 'Necropolis', 'City/town/settlement', 'fields-wd1-2026-09-26d-s016-rollback:ac28b46b-542e-48b7-adf9-32da0efd74c1:site_type', 'rollback of fields-wd1-2026-09-26d-s016: site_type ''City/town/settlement'' restored on Ancon Archaeological Site', '[{"source": "https://en.wikipedia.org/wiki/Ancon_(archaeological_site)", "url": "https://en.wikipedia.org/wiki/Ancon_(archaeological_site)", "quote": "It is one of the most important centers of the Peruvian archeology and features a vast necropolis of the pre-Hispanic era, with countless funerary sites.", "outcome": "found"}, {"source": "https://ancon1.com/arqueologia-en-ancon/", "url": "https://ancon1.com/arqueologia-en-ancon/", "quote": "Las primeras excavaciones científicas en el cementerio de Ancón fueron realizadas entre 1874 y 1875, por Wilheim Reiss y Alphons Stubel.", "outcome": "found"}, {"source": "https://archive.org/details/gri_33125012875577", "url": "https://archive.org/details/gri_33125012875577", "quote": "The necropolis of Ancon in Peru : a contribution to our knowledge of the culture and industries of the empire of the Incas being the results of excavations made on the spot", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0014)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia, the local Ancon heritage page and the Reiss & Stuebel excavation report all describe Ancon as a vast pre-Hispanic necropolis (cemetery); no source describes a town or settlement as what the site is, so Necropolis replaces City/town/settlement.", "value_page": null}]'::jsonb),
