    ('b0b4e4d6-ef79-4b2d-ad6b-62532b5ba54d'::uuid, 'period_start', '1001', '900', 'fields-wd1-2026-09-26d-s016-rollback:b0b4e4d6-ef79-4b2d-ad6b-62532b5ba54d:period_start', 'rollback of fields-wd1-2026-09-26d-s016: period_start ''900'' restored on Huaca del Dragón', '[{"source": "https://es.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n", "url": "https://es.wikipedia.org/wiki/Huaca_del_Drag%C3%B3n", "quote": "Estudios arquitectónicos e iconográficos modernos han determinado que la Huaca del Dragón fue edificada durante el período Chimú Temprano (aproximadamente en el siglo XI d. C.), enlazándose formalmente con las tradiciones artísticas desarrolladas en la costa norte peruana y descartando las antiguas teorías que le atribuían un origen moche o del Horizonte Medio.", "outcome": "found"}, {"source": "https://trujilloancestral.com/capitulos/huaca-del-dragon-arcoiris-chimu.html", "url": "https://trujilloancestral.com/capitulos/huaca-del-dragon-arcoiris-chimu.html", "quote": "Los Chimú construyeron la Huaca del Dragón probablemente en el siglo XI. Fue un templo dedicado al culto del agua", "outcome": "found"}, {"source": "https://www.lonelyplanet.com/points-of-interest/huaca-arco-iris/1165534", "url": "https://www.lonelyplanet.com/points-of-interest/huaca-arco-iris/1165534", "quote": "Dating from the 12th century, it is one of the better preserved of the Chimú temples", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0014)", "decision": "replace", "status": "MISSING", "reasoning": "Spanish Wikipedia (citing modern architectural and iconographic studies that reject the older Moche/Middle Horizon attribution) and a Trujillo heritage series date the construction to the Early Chimú 11th century AD, and Lonely Planet dates it to the 12th century; all place the start in 1000 - 1500 AD, not in the stored 500 - 1000 AD bucket, so the start becomes 1001.", "value_page": null}]'::jsonb),
